import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi } from 'vitest';
import { BookCard } from './BookCard';
import type { Book } from '../../types';

const book: Book = {
  id: 'abc-123',
  title: 'The Pragmatic Programmer',
  author: 'David Thomas',
  status: 'read',
};

describe('BookCard', () => {
  it('renders title', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByRole('heading', { name: book.title })).toBeInTheDocument();
  });

  it('renders author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText(book.author)).toBeInTheDocument();
  });

  it('renders status badge with correct text', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText(book.status)).toBeInTheDocument();
  });

  it('sets data-status attribute on badge to current status', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    const badge = screen.getByText(book.status);
    expect(badge).toHaveAttribute('data-status', 'read');
  });

  it('exposes an accessible label combining title and author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(
      screen.getByRole('button', { name: `${book.title} by ${book.author}` })
    ).toBeInTheDocument();
  });

  it('calls onClick with book id when clicked', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    await userEvent.click(screen.getByRole('button'));
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith(book.id);
  });

  it('calls onClick with book id when Enter is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    screen.getByRole('button').focus();
    await userEvent.keyboard('{Enter}');
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith(book.id);
  });

  it('does not call onClick when a non-Enter key is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    screen.getByRole('button').focus();
    await userEvent.keyboard('{Space}');
    expect(handleClick).not.toHaveBeenCalled();
  });

  it('renders status badge reflecting a different status value', () => {
    const readingBook: Book = { ...book, status: 'reading' };
    render(<BookCard book={readingBook} onClick={vi.fn()} />);
    const badge = screen.getByText('reading');
    expect(badge).toHaveAttribute('data-status', 'reading');
  });
});

