import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi } from 'vitest';
import { ChipBar } from './ChipBar';

const chips = [
  { id: 'read', label: 'Read' },
  { id: 'reading', label: 'Reading' },
  { id: 'want-to-read', label: 'Want to read' },
];

describe('ChipBar', () => {
  it('renders a button for each chip', () => {
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={vi.fn()} />);
    expect(screen.getAllByRole('button')).toHaveLength(chips.length);
  });

  it('renders each chip with its label', () => {
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={vi.fn()} />);
    for (const chip of chips) {
      expect(screen.getByRole('button', { name: chip.label })).toBeInTheDocument();
    }
  });

  it('unselected chips have aria-pressed="false"', () => {
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={vi.fn()} />);
    for (const chip of chips) {
      expect(screen.getByRole('button', { name: chip.label })).toHaveAttribute(
        'aria-pressed',
        'false'
      );
    }
  });

  it('selected chips have aria-pressed="true"', () => {
    render(<ChipBar chips={chips} selected={['read']} onSelectionChange={vi.fn()} />);
    expect(screen.getByRole('button', { name: 'Read' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'Reading' })).toHaveAttribute(
      'aria-pressed',
      'false'
    );
  });

  it('multiple chips can be selected simultaneously', () => {
    render(
      <ChipBar chips={chips} selected={['read', 'reading']} onSelectionChange={vi.fn()} />
    );
    expect(screen.getByRole('button', { name: 'Read' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'Reading' })).toHaveAttribute('aria-pressed', 'true');
    expect(screen.getByRole('button', { name: 'Want to read' })).toHaveAttribute(
      'aria-pressed',
      'false'
    );
  });

  it('clicking an unselected chip calls onSelectionChange with that chip added', async () => {
    const handleChange = vi.fn();
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Read' }));
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith(['read']);
  });

  it('clicking a selected chip calls onSelectionChange with that chip removed', async () => {
    const handleChange = vi.fn();
    render(<ChipBar chips={chips} selected={['read', 'reading']} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Read' }));
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith(['reading']);
  });

  it('does not mutate the selected array passed in', async () => {
    const handleChange = vi.fn();
    const selected: string[] = ['read'];
    render(<ChipBar chips={chips} selected={selected} onSelectionChange={handleChange} />);
    await userEvent.click(screen.getByRole('button', { name: 'Reading' }));
    // original array unchanged
    expect(selected).toEqual(['read']);
  });

  it('pressing Enter on a chip toggles it', async () => {
    const handleChange = vi.fn();
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={handleChange} />);
    screen.getByRole('button', { name: 'Read' }).focus();
    await userEvent.keyboard('{Enter}');
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith(['read']);
  });

  it('pressing Space on a chip toggles it', async () => {
    const handleChange = vi.fn();
    render(<ChipBar chips={chips} selected={[]} onSelectionChange={handleChange} />);
    screen.getByRole('button', { name: 'Read' }).focus();
    await userEvent.keyboard(' ');
    expect(handleChange).toHaveBeenCalledOnce();
    expect(handleChange).toHaveBeenCalledWith(['read']);
  });
});

