import { renderHook, waitFor } from '@testing-library/react';
import { describe, it, expect } from 'vitest';
import { useBooks } from './useBooks';

describe('useBooks', () => {
  it('initially reports loading with null data and no error', () => {
    const { result } = renderHook(() => useBooks());
    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeNull();
    expect(result.current.error).toBeNull();
  });

  it('transitions out of loading state after mount', async () => {
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(result.current.error).toBeNull();
  });

  it('populates data with the array returned by getBooks', async () => {
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    expect(Array.isArray(result.current.data)).toBe(true);
  });

  it('each book has the required fields from the Book type', async () => {
    const { result } = renderHook(() => useBooks());
    await waitFor(() => expect(result.current.loading).toBe(false));
    for (const book of result.current.data ?? []) {
      expect(book).toEqual(
        expect.objectContaining({
          id: expect.any(String),
          title: expect.any(String),
          author: expect.any(String),
          status: expect.stringMatching(/^(read|reading|want-to-read)$/),
        })
      );
    }
  });
});

